import os, re, json
from collections import Counter
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def lines(grid):
    H,W=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c]==bg or (r,c) in seen: continue
            col=grid[r][c]
            for dr,dc in ((1,1),(1,-1)):
                cells=[]
                rr,cc=r,c
                while 0<=rr<H and 0<=cc<W and grid[rr][cc]==col:
                    cells.append((rr,cc)); seen.add((rr,cc)); rr+=dr; cc+=dc
                # also extend backward
                rr,cc=r-dr,c-dc
                while 0<=rr<H and 0<=cc<W and grid[rr][cc]==col:
                    cells.append((rr,cc)); seen.add((rr,cc)); rr-=dr; cc-=dc
                if len(cells)>=2: res.append((col,cells,(dr,dc)))
    return bg,res

def transform(grid):
    H,W=len(grid),len(grid[0]); bg,Ls=lines(grid)
    out=[row[:] for row in grid]; cands=[]
    for col,cells,_ in Ls:
        for end,step in ((max(cells),1),(min(cells),-1)):
            rr,cc=end[0]+step*_[0], end[1]+step*_[1]; path=[]
            while 0<=rr<H and 0<=cc<W:
                if grid[rr][cc]!=bg: break
                path.append((rr,cc)); rr+=step*_[0]; cc+=step*_[1]
            else:
                if path: cands.append((col,path))
    assert len(cands)==1, cands
    col,path=cands[0]
    for r,c in path: out[r][c]=col
    return out

for k in sorted(G):
    if k.startswith('Demo'):
        print(k, transform(G[k+' input'])==G[k+' output'] if k.endswith('input') else '')
print(json.dumps(transform(G['Test input'])))

for k in sorted(G):
    if 'output' in k:
        ik=k.replace('output','input')
        try:
            print(k, transform(G[ik])==G[k])
        except AssertionError as e:
            print(k,'MULTI',e)
print(json.dumps(transform(G['Test input'])))

